def esc(s):return html.escape(s)
def annotate(key,xy=None,num=1):
 x=R[key]; im=Image.open(ROOT/x['file']).convert('RGB');w,h=im.size
 # Crop empty desktop height only, never replace screen content.
 if w>=1000:im=im.crop((0,0,w,min(h,1050)))
 d=ImageDraw.Draw(im)
 box=x.get('box')
 if xy:cx,cy=xy
 elif box and box['y']<im.height and box['x']<w:cx=box['x']+box['width']/2;cy=box['y']+box['height']/2
 else:cx,cy=(w*.5,min(im.height*.28,240))
 cx=max(35,min(w-35,cx));cy=max(35,min(im.height-35,cy))
 radius=28 if w<500 else 44;d.ellipse((cx-radius,cy-radius,cx+radius,cy+radius),outline=PINK,width=5)
 sx=max(25,cx-90);sy=max(28,cy-75);d.line((sx,sy,cx-radius*.6,cy-radius*.6),fill=PINK,width=5)
 d.ellipse((sx-17,sy-17,sx+17,sy+17),fill=PINK);d.text((sx,sy-3),str(num),font=font,fill='white',anchor='mm')
 out=ROOT/'screenshots'/(key+f'-marked-{num}.jpg');im.save(out,quality=91)
 return out,x
